  const router = useRouter();
  const searchParams = useSearchParams();
  const { assets } = useMarketSimulation();
  const btc = assets["BTC"] || DEMO_ASSETS["BTC"];

  const [strategy, setStrategy] = useState("BTC Trend 20/50");
  const [asset, setAsset] = useState("BTC/USD");
  const [period, setPeriod] = useState("2019 — 2026");
  const [capital, setCapital] = useState("100,000");

  const [chartMode, setChartMode] = useState<"EQUITY" | "DRAWDOWN" | "RETURNS" | "CANDLE">("EQUITY");
